package com.campusmart.controller;
import com.campusmart.entity.Product; import com.campusmart.dto.ProductDtos; import com.campusmart.service.ProductService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductService s;public ProductController(ProductService s){this.s=s;}@GetMapping public List<Product> all(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(required=false)Product.Condition condition,@RequestParam(required=false)BigDecimal maxPrice){return s.search(q,category,condition,maxPrice);}@GetMapping("/{id}") public Product get(@PathVariable Long id){return s.get(id);}@PostMapping public Product create(@Valid @RequestBody ProductDtos.Create d,Authentication a){return s.create(d,Long.valueOf(a.getName()));}@PutMapping("/{id}") public Product update(@PathVariable Long id,@Valid @RequestBody ProductDtos.Create d,Authentication a){return s.update(id,d,Long.valueOf(a.getName()),a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")));}@DeleteMapping("/{id}") public void delete(@PathVariable Long id,Authentication a){s.delete(id,Long.valueOf(a.getName()),a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")));}}
